    END IF;

    ai := ai || a;
    v_language := coalesce(ai->>'primary_language', 'en-IN');
    INSERT INTO public.agent_configs (organization_id, business_id, agent_name, primary_language,
      voice_id, greetings, capabilities, objectives)
    VALUES (_org, v_business, coalesce(ai->>'agent_name', 'Aria'), v_language,
      coalesce(ai->>'voice_id', 'ritu'),
      CASE WHEN ai->>'greeting' IS NULL THEN '{}'::jsonb
           ELSE jsonb_build_object(v_language, ai->>'greeting') END,
      coalesce(_initial->'agent'->'capabilities', '{}'),
      ARRAY(SELECT jsonb_array_elements_text(
        coalesce(_initial->'agent'->'objectives', '["answer_questions"]'))));
    v_created_agent := true;
  ELSIF a <> '{}' THEN
    SELECT coalesce(a->>'primary_language', primary_language),
           coalesce(a->>'greeting',
             -- A newly chosen language without a greeting gets the one on screen.
             CASE WHEN a ? 'primary_language'
                       AND NOT coalesce(greetings, '{}') ? (a->>'primary_language')
                  THEN ai->>'greeting' END)
      INTO v_language, v_greeting
      FROM public.agent_configs WHERE id = v_agent;
    UPDATE public.agent_configs SET
      agent_name = coalesce(a->>'agent_name', agent_name),
      primary_language = v_language,
      voice_id = coalesce(a->>'voice_id', voice_id),
      greetings = CASE WHEN v_greeting IS NULL THEN greetings
                       ELSE coalesce(greetings, '{}') || jsonb_build_object(v_language, v_greeting) END
    WHERE id = v_agent AND organization_id = _org
      AND ((a ? 'agent_name' AND agent_name IS DISTINCT FROM a->>'agent_name')
        OR (a ? 'voice_id' AND voice_id IS DISTINCT FROM a->>'voice_id')
        OR primary_language IS DISTINCT FROM v_language
        OR (v_greeting IS NOT NULL AND greetings->>v_language IS DISTINCT FROM v_greeting));
  END IF;

  UPDATE public.organizations SET onboarding_completed = true
   WHERE id = _org AND NOT onboarding_completed;

  RETURN jsonb_build_object('business_id', v_business,
    'created_business', v_created_business, 'created_agent', v_created_agent);
END $$;
REVOKE ALL ON FUNCTION public.lock_business_setup(uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.lock_business_setup(uuid) TO authenticated;
REVOKE ALL ON FUNCTION public.save_business_setup(uuid, jsonb, jsonb) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.save_business_setup(uuid, jsonb, jsonb) TO authenticated;
$gate_outbound_mig$]);

-- ===== Check, inside the same transaction: any failure rolls everything back =====
DO $check$
BEGIN
  IF NOT ((SELECT NOT prosecdef AND proconfig = ARRAY['search_path=public'] FROM pg_proc WHERE oid = to_regprocedure('public.save_business_setup(uuid, jsonb, jsonb)'))
     AND has_function_privilege('authenticated', 'public.save_business_setup(uuid, jsonb, jsonb)', 'EXECUTE')
     AND NOT has_function_privilege('anon', 'public.save_business_setup(uuid, jsonb, jsonb)', 'EXECUTE') AND (SELECT NOT prosecdef AND proconfig = ARRAY['search_path=public'] FROM pg_proc WHERE oid = to_regprocedure('public.lock_business_setup(uuid)'))
     AND has_function_privilege('authenticated', 'public.lock_business_setup(uuid)', 'EXECUTE')
     AND NOT has_function_privilege('anon', 'public.lock_business_setup(uuid)', 'EXECUTE')) THEN
    RAISE EXCEPTION 'GATE_20261205090000_CHECK: the migration objects are not as expected';
  END IF;
  IF (SELECT md5(statements[1]) FROM supabase_migrations.schema_migrations WHERE version = '20261205090000') IS DISTINCT FROM '227c7c32cfb4b57d527b326b016dc255' THEN
    RAISE EXCEPTION 'GATE_20261205090000_CHECK: recorded migration text differs';
  END IF;
  IF md5((SELECT 'campaigns:' || count(*) || ':' || coalesce(md5(string_agg((to_jsonb(x))::text, '|' ORDER BY (to_jsonb(x))::text)), '-') FROM public.campaigns x) || ';' || (SELECT 'campaign_contacts:' || count(*) || ':' || coalesce(md5(string_agg((to_jsonb(x))::text, '|' ORDER BY (to_jsonb(x))::text)), '-') FROM public.campaign_contacts x) || ';' || (SELECT 'campaign_uploads:' || count(*) || ':' || coalesce(md5(string_agg((to_jsonb(x))::text, '|' ORDER BY (to_jsonb(x))::text)), '-') FROM public.campaign_uploads x) || ';' || (SELECT 'contacts:' || count(*) || ':' || coalesce(md5(string_agg((to_jsonb(x))::text, '|' ORDER BY (to_jsonb(x))::text)), '-') FROM public.contacts x) || ';' || (SELECT 'phone_numbers:' || count(*) || ':' || coalesce(md5(string_agg((to_jsonb(x))::text, '|' ORDER BY (to_jsonb(x))::text)), '-') FROM public.phone_numbers x) || ';' || (SELECT 'agent_configs:' || count(*) || ':' || coalesce(md5(string_agg((to_jsonb(x))::text, '|' ORDER BY (to_jsonb(x))::text)), '-') FROM public.agent_configs x) || ';' || (SELECT 'platform_settings:' || count(*) || ':' || coalesce(md5(string_agg((to_jsonb(x))::text, '|' ORDER BY (to_jsonb(x))::text)), '-') FROM public.platform_settings x) || ';' || (SELECT 'call_logs:' || count(*) || ':' || coalesce(md5(string_agg((to_jsonb(x))::text, '|' ORDER BY (to_jsonb(x))::text)), '-') FROM public.call_logs x) || ';' || (SELECT 'wallet_transactions:' || count(*) || ':' || coalesce(md5(string_agg((to_jsonb(x))::text, '|' ORDER BY (to_jsonb(x))::text)), '-') FROM public.wallet_transactions x) || ';' || (SELECT 'webhook_events:' || count(*) || ':' || coalesce(md5(string_agg((to_jsonb(x))::text, '|' ORDER BY (to_jsonb(x))::text)), '-') FROM public.webhook_events x) || ';' || (SELECT 'organizations:' || count(*) || ':' || coalesce(md5(string_agg((to_jsonb(x))::text, '|' ORDER BY (to_jsonb(x))::text)), '-') FROM public.organizations x) || ';' || (SELECT 'businesses:' || count(*) || ':' || coalesce(md5(string_agg((to_jsonb(x))::text, '|' ORDER BY (to_jsonb(x))::text)), '-') FROM public.businesses x) || ';' || (SELECT 'business_hours:' || count(*) || ':' || coalesce(md5(string_agg((to_jsonb(x))::text, '|' ORDER BY (to_jsonb(x))::text)), '-') FROM public.business_hours x) || ';' || (SELECT 'services:' || count(*) || ':' || coalesce(md5(string_agg((to_jsonb(x))::text, '|' ORDER BY (to_jsonb(x))::text)), '-') FROM public.services x) || ';' || (SELECT 'faqs:' || count(*) || ':' || coalesce(md5(string_agg((to_jsonb(x))::text, '|' ORDER BY (to_jsonb(x))::text)), '-') FROM public.faqs x) || ';' || (SELECT 'business_rules:' || count(*) || ':' || coalesce(md5(string_agg((to_jsonb(x))::text, '|' ORDER BY (to_jsonb(x))::text)), '-') FROM public.business_rules x) || ';' || (SELECT 'subscriptions:' || count(*) || ':' || coalesce(md5(string_agg((to_jsonb(x))::text, '|' ORDER BY (to_jsonb(x))::text)), '-') FROM public.subscriptions x) || ';' || (SELECT 'provisioning_runs:' || count(*) || ':' || coalesce(md5(string_agg((to_jsonb(x))::text, '|' ORDER BY (to_jsonb(x))::text)), '-') FROM public.provisioning_runs x) || ';' || (SELECT 'provisioning_run_events:' || count(*) || ':' || coalesce(md5(string_agg((to_jsonb(x))::text, '|' ORDER BY (to_jsonb(x))::text)), '-') FROM public.provisioning_run_events x)) IS DISTINCT FROM current_setting('gate_outbound.data_before', true) THEN
    RAISE EXCEPTION 'GATE_20261205090000_CHECK: existing data changed';
  END IF;
END
$check$;

SELECT json_build_object(
  'applied', '20261205090000',
  'system_identifier', (SELECT system_identifier::text FROM pg_control_system()),
  'database', current_database(),
  'latest_migration', (SELECT max(version) FROM supabase_migrations.schema_migrations),
  'objects_present', ((SELECT NOT prosecdef AND proconfig = ARRAY['search_path=public'] FROM pg_proc WHERE oid = to_regprocedure('public.save_business_setup(uuid, jsonb, jsonb)'))
     AND has_function_privilege('authenticated', 'public.save_business_setup(uuid, jsonb, jsonb)', 'EXECUTE')
     AND NOT has_function_privilege('anon', 'public.save_business_setup(uuid, jsonb, jsonb)', 'EXECUTE') AND (SELECT NOT prosecdef AND proconfig = ARRAY['search_path=public'] FROM pg_proc WHERE oid = to_regprocedure('public.lock_business_setup(uuid)'))
     AND has_function_privilege('authenticated', 'public.lock_business_setup(uuid)', 'EXECUTE')
     AND NOT has_function_privilege('anon', 'public.lock_business_setup(uuid)', 'EXECUTE')),
  'existing_data_unchanged', md5((SELECT 'campaigns:' || count(*) || ':' || coalesce(md5(string_agg((to_jsonb(x))::text, '|' ORDER BY (to_jsonb(x))::text)), '-') FROM public.campaigns x) || ';' || (SELECT 'campaign_contacts:' || count(*) || ':' || coalesce(md5(string_agg((to_jsonb(x))::text, '|' ORDER BY (to_jsonb(x))::text)), '-') FROM public.campaign_contacts x) || ';' || (SELECT 'campaign_uploads:' || count(*) || ':' || coalesce(md5(string_agg((to_jsonb(x))::text, '|' ORDER BY (to_jsonb(x))::text)), '-') FROM public.campaign_uploads x) || ';' || (SELECT 'contacts:' || count(*) || ':' || coalesce(md5(string_agg((to_jsonb(x))::text, '|' ORDER BY (to_jsonb(x))::text)), '-') FROM public.contacts x) || ';' || (SELECT 'phone_numbers:' || count(*) || ':' || coalesce(md5(string_agg((to_jsonb(x))::text, '|' ORDER BY (to_jsonb(x))::text)), '-') FROM public.phone_numbers x) || ';' || (SELECT 'agent_configs:' || count(*) || ':' || coalesce(md5(string_agg((to_jsonb(x))::text, '|' ORDER BY (to_jsonb(x))::text)), '-') FROM public.agent_configs x) || ';' || (SELECT 'platform_settings:' || count(*) || ':' || coalesce(md5(string_agg((to_jsonb(x))::text, '|' ORDER BY (to_jsonb(x))::text)), '-') FROM public.platform_settings x) || ';' || (SELECT 'call_logs:' || count(*) || ':' || coalesce(md5(string_agg((to_jsonb(x))::text, '|' ORDER BY (to_jsonb(x))::text)), '-') FROM public.call_logs x) || ';' || (SELECT 'wallet_transactions:' || count(*) || ':' || coalesce(md5(string_agg((to_jsonb(x))::text, '|' ORDER BY (to_jsonb(x))::text)), '-') FROM public.wallet_transactions x) || ';' || (SELECT 'webhook_events:' || count(*) || ':' || coalesce(md5(string_agg((to_jsonb(x))::text, '|' ORDER BY (to_jsonb(x))::text)), '-') FROM public.webhook_events x) || ';' || (SELECT 'organizations:' || count(*) || ':' || coalesce(md5(string_agg((to_jsonb(x))::text, '|' ORDER BY (to_jsonb(x))::text)), '-') FROM public.organizations x) || ';' || (SELECT 'businesses:' || count(*) || ':' || coalesce(md5(string_agg((to_jsonb(x))::text, '|' ORDER BY (to_jsonb(x))::text)), '-') FROM public.businesses x) || ';' || (SELECT 'business_hours:' || count(*) || ':' || coalesce(md5(string_agg((to_jsonb(x))::text, '|' ORDER BY (to_jsonb(x))::text)), '-') FROM public.business_hours x) || ';' || (SELECT 'services:' || count(*) || ':' || coalesce(md5(string_agg((to_jsonb(x))::text, '|' ORDER BY (to_jsonb(x))::text)), '-') FROM public.services x) || ';' || (SELECT 'faqs:' || count(*) || ':' || coalesce(md5(string_agg((to_jsonb(x))::text, '|' ORDER BY (to_jsonb(x))::text)), '-') FROM public.faqs x) || ';' || (SELECT 'business_rules:' || count(*) || ':' || coalesce(md5(string_agg((to_jsonb(x))::text, '|' ORDER BY (to_jsonb(x))::text)), '-') FROM public.business_rules x) || ';' || (SELECT 'subscriptions:' || count(*) || ':' || coalesce(md5(string_agg((to_jsonb(x))::text, '|' ORDER BY (to_jsonb(x))::text)), '-') FROM public.subscriptions x) || ';' || (SELECT 'provisioning_runs:' || count(*) || ':' || coalesce(md5(string_agg((to_jsonb(x))::text, '|' ORDER BY (to_jsonb(x))::text)), '-') FROM public.provisioning_runs x) || ';' || (SELECT 'provisioning_run_events:' || count(*) || ':' || coalesce(md5(string_agg((to_jsonb(x))::text, '|' ORDER BY (to_jsonb(x))::text)), '-') FROM public.provisioning_run_events x)) = current_setting('gate_outbound.data_before', true),
  'lock_timeout', current_setting('lock_timeout'),
  'statement_timeout', current_setting('statement_timeout')
) AS gate_outbound_result;
